const std = @import("std");

fn gcd(a: u32, b: u32) u32 {
    if (b == 0) return a;
    return gcd(b, a % b);
}

fn lcm(a: u32, b: u32) u32 {
    return a / gcd(a, b) * b;
}

pub fn main() !void {
    const x: u32 = 48;
    const y: u32 = 18;

    std.debug.print("GCD({}, {}) = {}\n", .{x, y, gcd(x, y)});
    std.debug.print("LCM({}, {}) = {}\n", .{x, y, lcm(x, y)});
}
